(function(root){
  'use strict';
  const C=root.HHMathCore,D=root.HHMathCoreContent,esc=C.escape;
  const tabs=[['tutor','Trợ giảng','spark'],['theory','Kiến thức','book'],['practice','Luyện tập','target'],['lab','3D & đồ thị','cube'],['casio','Casio','calc'],['notebook','Sổ tay','note']];
  const paths={spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3ZM12 6v15',target:'M20 12a8 8 0 1 1-8-8M16 3h5v5M21 3l-9 9M15 12a3 3 0 1 1-3-3',cube:'M12 3l9 5v9l-9 5-9-5V8ZM3 8l9 5 9-5M12 13v9',calc:'M5 3h14v18H5ZM8 6h8v4H8ZM8 14h1m6 0h1M8 17h1m6 0h1',note:'M5 3h12l3 3v15H5ZM8 9h9M8 13h9M8 17h6',image:'M3 4h18v16H3ZM3 16l6-6 4 4 3-3 5 5M15 8h.01',arrow:'M5 12h14M13 6l6 6-6 6',check:'M5 12l4 4L19 6',save:'M5 3h14v18l-7-4-7 4Z'};
  const icon=name=>'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]?'<path d="'+paths[name]+'"/>':'<path d="M5 12h14"/>')+'</svg>';
  const button=(action,label,attrs='')=>'<button type="button" data-mc-action="'+action+'" '+attrs+'>'+label+'</button>';
  const link=(view,label,attrs='')=>'<a href="#/mathcore'+(view==='tutor'?'':'/'+view)+'" '+attrs+'>'+label+'</a>';
  const topicOptions=selected=>D.topics.map(t=>'<option value="'+t.id+'"'+(selected===t.id?' selected':'')+'>'+esc(t.title)+'</option>').join('');
  const formula=value=>'<div class="mc-formula">'+esc(value)+'</div>';
  let active=null;
  function mount(host,options={}){
    unmount();const segments=String(options.route||'/mathcore').split('?')[0].split('/').filter(Boolean),rawView=segments[1]||'tutor',view=tabs.some(t=>t[0]===rawView)?rawView:rawView==='photo'?'tutor':'missing',query=new URLSearchParams(String(options.route||'').split('?')[1]||''),owner=options.currentUser,key=C.preferenceKey(owner);
    let prefs,protectedState=false,storageError='',rawBackup=null;try{rawBackup=root.localStorage.getItem(key);prefs=C.preferences(rawBackup===null?null:JSON.parse(rawBackup));}catch{prefs=C.defaults();protectedState=true;}
    let ocrSession=null,ocrTimer=0;
    let alive=true,service=null,serviceError='',notice='',busy=false,request=null,requestVersion=0,mode=rawView==='photo'?'photo':'text',online=false,problem=prefs.draft?.problem||'',attempt=prefs.draft?.attempt||'',lesson=null,revealed=false,hintIndex=0,localChecks=[],photo=null,photoResult=null,imageSequence=0,saveTimer=0,theoryQuery='',selectedTopic=D.topic(query.get('topic')||prefs.topic).id,quiz=null,quizAnswers={},quizChecked=false,quizIndex=0,solid=null,graph=null,resetArmed=false;
    const lifecycle=new AbortController();
    let lastRaw=rawBackup,baseline=JSON.parse(JSON.stringify(prefs));
    function persist(){if(protectedState)return false;try{
      const current=root.localStorage.getItem(key);if(current!==lastRaw){let remote;try{remote=C.preferences(current===null?null:JSON.parse(current));}catch{rawBackup=current;protectedState=true;showStorage();return false;}
        const merged={...remote};for(const name of ['topic','notes','draft','casioModel'])if(JSON.stringify(prefs[name])!==JSON.stringify(baseline[name]))merged[name]=prefs[name];
        if(JSON.stringify(prefs.attempts)!==JSON.stringify(baseline.attempts))merged.attempts=[...new Map([...remote.attempts,...prefs.attempts].map(row=>[row.id,row])).values()].slice(-500);
        if(JSON.stringify(prefs.saved)!==JSON.stringify(baseline.saved)){const removed=new Set(baseline.saved.filter(row=>!prefs.saved.some(x=>x.problem===row.problem)).map(row=>row.problem));merged.saved=[...new Map([...remote.saved,...prefs.saved].filter(row=>!removed.has(row.problem)).map(row=>[row.problem,row])).values()].sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,100);}prefs=merged;
      }
      const serialized=JSON.stringify(prefs);root.localStorage.setItem(key,serialized);lastRaw=serialized;baseline=JSON.parse(serialized);storageError='';return true;
    }catch{storageError='Chưa lưu được trên thiết bị. Hãy xuất bản sao từ Sổ tay.';showStorage();return false;}}
    function scheduleSave(){root.clearTimeout(saveTimer);saveTimer=root.setTimeout(persist,300);}
    function showStorage(){const el=host.querySelector('[data-mc-storage]');if(el){el.textContent=protectedState?'Sổ tay hiện có cần khôi phục. Các thay đổi mới chưa được ghi đè; mở Sổ tay để tải bản sao.':storageError;el.hidden=!el.textContent;}}
    const topic=()=>D.topic(selectedTopic),canAI=()=>service?.configured===true&&Boolean(owner?.id||owner?._id)&&!owner?.guest;
    const apiBase=String(root.HH_API_BASE||location.origin).replace(/\/$/,'');
    async function api(resource,body,signal){const token=root.HHAuthSession?.token?.()||'';const response=await root.fetch(apiBase+'/api/mathcore/'+resource,{method:body?'POST':'GET',credentials:'include',cache:'no-store',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{}),signal});const data=await response.json().catch(()=>({}));if(!response.ok)throw Object.assign(Error(data.error||'Chưa kết nối được MATHCORE AI.'),{status:response.status});return data;}
    function serviceMarkup(){return serviceError?'Không kết nối được AI · Các công cụ toán vẫn dùng được':!service?'Đang kiểm tra trợ giảng AI…':!service.configured?'AI trực tuyến chưa được kích hoạt':canAI()?'AI trực tuyến sẵn sàng':'Đăng nhập để dùng AI trực tuyến';}
    function updateService(){const chip=host.querySelector('[data-mc-service]');if(chip){chip.textContent=serviceMarkup();chip.dataset.ready=canAI()?'true':'false';}const toggle=host.querySelector('[name=online]');if(toggle){toggle.disabled=!canAI()||busy;if(!canAI()){online=false;toggle.checked=false;}}const info=host.querySelector('[data-mc-ai-info]');if(info)info.textContent=serviceMarkup()+'.';host.querySelectorAll('[data-mc-requires-ai]').forEach(el=>{el.disabled=!canAI()||busy||!photo;});}
    function feedback(message){notice=message;const el=host.querySelector('[data-mc-notice]');if(el){el.textContent=message;el.hidden=!message;}}
    function destroyGraphics(){solid?.destroy();graph?.destroy();solid=null;graph=null;}
    function heading(kicker,title,body){return '<header class="mc-heading"><small>'+esc(kicker)+'</small><h1 tabindex="-1">'+esc(title)+'</h1><p>'+esc(body)+'</p></header>';}
    function introArt(){return '<div class="mc-hero-art" aria-hidden="true"><svg viewBox="0 0 340 245" fill="none"><defs><linearGradient id="mcOrbit" x1="30" y1="200" x2="300" y2="30" gradientUnits="userSpaceOnUse"><stop stop-color="#25d9f8"/><stop offset="1" stop-color="#9361ff"/></linearGradient></defs><path d="M25 205H320M55 25V226" stroke="#8bb7d3" stroke-opacity=".3"/><path d="M30 170C105 210 98 52 163 92S222 218 315 42" stroke="url(#mcOrbit)" stroke-width="3"/><path d="M137 58l58-32 58 32v70l-58 33-58-33Z" fill="#4776ff" fill-opacity=".13" stroke="#79d7ec" stroke-width="1.5"/><path d="M137 58l58 34 58-34M195 92v69" stroke="#79d7ec" stroke-width="1.5"/><circle cx="163" cy="92" r="7" fill="#ffd166"/><circle cx="280" cy="90" r="4" fill="#ff8066"/><rect x="53" y="18" width="86" height="35" rx="10" fill="#172e47" stroke="#324f6c"/><text x="68" y="41" fill="#d3edf7" font-size="17" font-family="system-ui">f′(x) = 2x</text><rect x="219" y="173" width="98" height="39" rx="12" fill="#172e47" stroke="#324f6c"/><text x="235" y="199" fill="#ffd166" font-size="21" font-family="system-ui">∑ · √ · π</text><circle cx="82" cy="154" r="34" stroke="#9361ff" stroke-opacity=".35" stroke-dasharray="4 6"/></svg></div>';}
    function featureCards(){return '<div class="mc-feature-grid">'+[
      ['theory','book','Hiểu từ bản chất','24 chủ đề · công thức · điều kiện','blue'],['practice','target','Luyện đúng nhịp','Bài mới, ba mức độ, nhận xét sau khi làm','coral'],['lab','cube','Chạm vào Toán học','Xoay hình 3D, thiết diện & tiếp tuyến','violet'],['photo','image','Nhìn lại từng dòng','Đọc bài qua ảnh, tìm chỗ cần sửa','cyan']
    ].map(([route,i,title,body,tint])=>link(route,icon(i)+'<strong>'+title+'</strong><span>'+body+'</span><b aria-hidden="true">↗</b>','class="mc-feature" data-tint="'+tint+'"')).join('')+'</div>';}
    function tutorView(){return '<section class="mc-hero"><div><span class="mc-eyebrow">HIỂU CÁCH LÀM. TỰ TÌM ĐÁP ÁN.</span><h1 tabindex="-1">Một gợi ý đúng lúc.<br><em>Một bước tiến của em.</em></h1><p>Từ công thức đầu tiên đến bài toán khó: cùng tháo gỡ từng bước, nhìn rõ hình và hiểu vì sao.</p><div class="mc-hero-actions">'+button('focus-problem','Nhập đề bài '+icon('arrow'),'class="mc-primary"')+link('theory','Khám phá kiến thức')+'</div><div class="mc-hero-tags"><span>'+icon('check')+' Gợi mở tư duy</span><span>'+icon('cube')+' Hình học tương tác</span></div></div>'+introArt()+'</section>'+featureCards()+'<div class="mc-tutor-grid"><section class="mc-panel mc-composer"><div class="mc-panel-title"><div><small>BÀN HỌC CỦA EM</small><h2>Hôm nay mình học gì?</h2></div>'+icon('spark')+'</div><div class="mc-segment" role="group" aria-label="Cách nhập bài">'+button('mode','Nhập đề bài','data-mode="text" aria-pressed="'+(mode==='text')+'"')+button('mode',icon('image')+' Sửa bài qua ảnh','data-mode="photo" aria-pressed="'+(mode==='photo')+'"')+'</div><form data-mc-tutor-form><label>Chủ đề<select name="topic">'+topicOptions(selectedTopic)+'</select></label><label>Đề bài hoặc điều em muốn hiểu<textarea name="problem" rows="4" maxlength="5000" placeholder="Ví dụ: 2x + 3 = 11. Vì sao chuyển vế phải đổi dấu?">'+esc(problem)+'</textarea></label>'+(mode==='photo'?photoView():'<details class="mc-attempt"'+(attempt?' open':'')+'><summary>Thêm bài em đã làm để kiểm tra</summary><label>Mỗi phép biến đổi trên một dòng<textarea name="attempt" rows="4" maxlength="8000" placeholder="2x + 3 = 11&#10;2x = 14&#10;x = 7">'+esc(attempt)+'</textarea></label><p>Công cụ cục bộ đối chiếu các dòng phương trình đa thức. AI có thể nhận xét bài làm rộng hơn.</p></details><label class="mc-toggle"><input type="checkbox" name="online"'+(online?' checked':'')+(!canAI()?' disabled':'')+'> Dùng trợ giảng AI trực tuyến</label><small data-mc-ai-info>'+esc(serviceMarkup())+'.</small>')+'<div class="mc-actions">'+(mode==='photo'?button('ocr',icon('image')+' Quét trên thiết bị','class="mc-primary"'+(!photo?' disabled':''))+'<button type="submit" data-mc-requires-ai'+(!canAI()||!photo?' disabled':'')+'>'+icon('image')+' AI nhận xét ảnh</button>':'<button type="submit" class="mc-primary">'+icon('spark')+' Bắt đầu từ một gợi ý</button>')+button('sample','Thử bài mẫu')+'</div><p class="mc-muted">'+(mode==='photo'?'Quét trên thiết bị không gửi ảnh. Chỉ nút “AI nhận xét ảnh” mới gửi ảnh để phân tích trực tuyến; ảnh không lưu vào sổ tay.':'Không cần AI để giải phương trình bậc 1–2, học bài mẫu hoặc luyện trắc nghiệm.')+'</p></form></section><section class="mc-panel mc-guidance" aria-label="Hướng dẫn giải" data-mc-guidance>'+guidance()+'</section></div>';
    }
    function photoView(){return '<div class="mc-photo-upload"><label>'+icon('image')+' Chọn ảnh bài làm<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><label class="mc-camera">Chụp ảnh<input type="file" name="camera" accept="image/*" capture="environment"></label><small>JPEG, PNG, WebP · tối đa 10 MB. Đặt trang giấy phẳng, đủ sáng và chụp rõ toàn bộ dòng.</small></div>'+(photo?'<div class="mc-photo-stage"><img src="'+esc(photo.url)+'" alt="Bài làm em vừa chọn để kiểm tra" data-mc-photo-image><div class="mc-photo-boxes">'+(photoResult?.observations||[]).map((o,i)=>o.box?'<span style="left:'+(o.box.x*100)+'%;top:'+(o.box.y*100)+'%;width:'+(o.box.w*100)+'%;height:'+(o.box.h*100)+'%" data-status="'+esc(o.status)+'" title="'+esc(o.note)+'"><b>'+(i+1)+'</b></span>':'').join('')+'</div></div><div class="mc-inline"><small>Ảnh đã thu nhỏ: '+photo.width+' × '+photo.height+' · '+Math.round(photo.bytes/1024)+' KB</small>'+button('remove-photo','Bỏ ảnh')+'</div>':'');}
    function guidance(){if(busy)return '<div class="mc-working" role="status"><span class="mc-loader"></span><h2>Đang đọc bài của em…</h2><p>Trợ giảng đang xem đề bài, điều kiện và từng phép biến đổi.</p>'+button('cancel','Hủy yêu cầu')+'</div>';
      if(mode==='photo'&&photoResult)return photoGuidance();
      if(!lesson)return '<div class="mc-welcome"><span class="mc-welcome-symbol">∑</span><small>MÌNH CÙNG BẮT ĐẦU</small><h2>Không vội đến đáp số.</h2><p>Chọn chủ đề, nhập câu hỏi hoặc thử bài mẫu. Mỗi gợi ý sẽ giúp em tự tìm bước tiếp theo.</p><ol><li><span>01</span> Đọc đề & tìm điều kiện</li><li><span>02</span> Chọn công thức phù hợp</li><li><span>03</span> Tự làm, rồi kiểm tra lại</li></ol></div>';
      return '<div class="mc-result-heading"><small class="mc-kicker">'+(lesson.provider==='openai'?'AI TRỰC TUYẾN':'CÔNG CỤ TOÁN CỤC BỘ')+'</small><span>'+esc(topic().domain)+'</span></div><h2>'+esc(lesson.title||'Cùng tìm cách làm')+'</h2>'+formula(lesson.problem||problem)+(lesson.interpretation?'<p>'+esc(lesson.interpretation)+'</p>':'')+(lesson.reference?'<aside class="mc-notice">'+esc(lesson.reference)+'</aside>':'')+(lesson.conditions?.length?'<details class="mc-conditions"><summary>Điều kiện & lưu ý</summary><ul>'+lesson.conditions.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul></details>':'')+'<div class="mc-hint"><small>GỢI Ý '+(hintIndex+1)+' / '+lesson.hints.length+'</small><p>'+esc(lesson.hints[hintIndex])+'</p></div><label>Thử viết bước tiếp theo<textarea name="thinking" rows="2" maxlength="1000" placeholder="Em nghĩ bước tiếp theo là…">'+esc(lesson.thinking||'')+'</textarea></label><div class="mc-actions">'+button('prev-hint','← Gợi ý trước',hintIndex===0?'disabled':'')+button('next-hint','Gợi ý tiếp →',hintIndex>=lesson.hints.length-1?'disabled':'')+button('check-thinking',lesson.provider==='openai'?'Nhận xét bước em viết · AI':'Kiểm tra bước em viết')+'</div>'+checksView(localChecks.length?localChecks:lesson.checks||[])+uncertainties(lesson.uncertainties||[])+'<div class="mc-reveal-actions">'+button('reveal',revealed?'Thu gọn lời giải':'Em đã thử — xem lời giải','class="mc-secondary"')+(revealed?button('save',icon('save')+' Lưu vào sổ tay'):'')+'</div>'+(revealed?'<div class="mc-solution"><h3>Lời giải để đối chiếu</h3><ol>'+lesson.steps.map(s=>'<li><strong>'+esc(s.title)+'</strong>'+(s.text?'<p>'+esc(s.text)+'</p>':'')+(s.formula?formula(s.formula):'')+'</li>').join('')+'</ol><div class="mc-answer"><small>KẾT QUẢ</small><strong>'+esc(lesson.answer||'Đề cần làm rõ thêm trước khi kết luận.')+'</strong></div>'+(lesson.alternative?'<details><summary>Một cách nhìn khác</summary><p>'+esc(lesson.alternative)+'</p></details>':'')+(lesson.reflect?'<p>'+esc(lesson.reflect)+'</p>':'')+'</div>':'');
    }
    function photoGuidance(){const local=photoResult.provider==='ocr-local';return '<small class="mc-kicker">ĐỌC ẢNH · '+(local?'OCR TRÊN THIẾT BỊ':'AI TRỰC TUYẾN')+'</small><h2>Nhìn lại từng dòng</h2><p>'+esc(photoResult.summary)+'</p>'+(local?'<label>Nội dung đọc được — em hãy sửa và xác nhận<textarea name="ocrReadBack" rows="5" maxlength="9000">'+esc(photoResult.readBack)+'</textarea></label>'+button('compare-ocr','Đã xác nhận — đối chiếu từng dòng','class="mc-secondary"'):'<details open><summary>Nội dung đọc được — em hãy xác nhận</summary><pre class="mc-readback">'+esc(photoResult.readBack)+'</pre></details>')+'<section data-mc-photo-findings>'+photoResult.observations.map((o,i)=>'<article class="mc-observation" data-status="'+esc(o.status)+'"><b>'+(i+1)+'. '+esc(o.status==='review'?'Cần xem lại':o.status==='equivalent'?'Phép biến đổi phù hợp':'Chưa kiểm chứng được')+'</b><blockquote>'+esc(o.quote)+'</blockquote><p>'+esc(o.note)+'</p></article>').join('')+'</section>'+uncertainties(photoResult.uncertainties)+'<aside class="mc-hint"><small>EM THỬ NGHĨ XEM</small><p>'+esc(photoResult.nextHint)+'</p></aside><p class="mc-muted">'+(local?'Chỉ đối chiếu các phương trình đa thức bậc 1–2 tỉ lệ với đề gốc. Nếu em sửa bản chép, ứng dụng sẽ bỏ vị trí trên ảnh để tránh đánh dấu sai.':'Vị trí trên ảnh và nhận xét do AI đề xuất. Kiểm tra lại ký hiệu đọc được trước khi sửa bài.')+'</p>';}
    function checksView(rows){return rows.length?'<section class="mc-checks"><h3>Nhận xét bài em đã làm</h3>'+rows.map(o=>'<article class="mc-observation" data-status="'+esc(o.status)+'"><b>'+esc(o.line?'Dòng '+o.line:o.status==='review'?'Cần xem lại':'Nhận xét')+'</b><blockquote>'+esc(o.text||o.quote)+'</blockquote><p>'+esc(o.note)+'</p>'+(o.scope?'<small>'+esc(o.scope)+'</small>':'')+'</article>').join('')+'</section>':'';}
    function uncertainties(rows){return rows?.length?'<aside class="mc-notice"><strong>Những điểm cần làm rõ</strong><ul>'+rows.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul></aside>':'';}
    function theoryView(){return heading('THƯ VIỆN KIẾN THỨC','Hiểu công thức. Nhớ cách dùng.','24 chủ đề từ nền tảng đến toán đại học nhập môn, có điều kiện áp dụng, lỗi thường gặp và ví dụ tự học.')+'<label class="mc-search">Tìm chủ đề, công thức hoặc từ khóa<input type="search" name="theoryQuery" value="'+esc(theoryQuery)+'" placeholder="Đạo hàm, xác suất, hình học…" autocomplete="off"></label><div class="mc-theory-layout"><nav class="mc-topic-list" aria-label="Chủ đề toán học" data-mc-topic-list>'+topicList()+'</nav><article class="mc-panel mc-lesson" data-mc-theory-detail>'+theoryDetail()+'</article></div><details class="mc-panel mc-sources"><summary>Tài liệu đọc thêm & nguồn tham khảo</summary><p>Các bài giảng và ví dụ tiếng Việt tại đây do HH biên soạn; các liên kết dưới giúp em đọc sâu hơn.</p>'+D.sources.map(s=>'<p><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+' ↗</a><br><small>'+esc(s.note)+'</small></p>').join('')+'</details>';}
    function topicList(){const q=C.fold(theoryQuery),rows=D.topics.filter(t=>C.fold([t.title,t.domain,t.summary,...t.formulas].join(' ')).includes(q));return rows.length?rows.map(t=>button('topic','<span>'+esc(t.domain)+'</span><strong>'+esc(t.title)+'</strong>','data-topic="'+t.id+'"'+(selectedTopic===t.id?' aria-current="true"':''))).join(''):'<p role="status">Không tìm thấy chủ đề. Thử “hàm số” hoặc “phương trình”.</p>';}
    function theoryDetail(){const t=topic();return '<small class="mc-kicker">'+esc(t.stage)+'</small><h2>'+esc(t.title)+'</h2><p>'+esc(t.summary)+'</p><h3>Công thức cần nhớ</h3>'+t.formulas.map(formula).join('')+'<aside class="mc-conditions"><strong>Dùng khi nào?</strong><p>'+esc(t.conditions)+'</p></aside><h3>Thử một ví dụ</h3>'+formula(t.problem)+'<p>'+esc(t.hints[0])+'</p><div class="mc-actions">'+button('study-sample',icon('spark')+' Học từng bước')+(D.practiceTopics.includes(t.id)?link('practice','Luyện chủ đề này','class="mc-link-button" data-mc-practice-topic="'+t.id+'"'):'')+'</div><aside class="mc-mistake"><strong>Lỗi dễ gặp</strong><p>'+esc(t.mistake)+'</p></aside><details><summary>Xem lời giải ví dụ</summary><ol>'+t.steps.map(s=>'<li><b>'+esc(s.title)+'</b>'+formula(s.formula)+'</li>').join('')+'</ol><p>'+esc(t.reflect)+'</p></details>';}
    function practiceView(){return heading('TỰ LÀM TRƯỚC. NHẬN XÉT SAU.','Một chút mỗi ngày, vững hơn từng bước.','Tạo bộ bài trắc nghiệm mới theo chủ đề. Kết quả chỉ được lưu sau khi em nộp bài.')+'<form class="mc-panel mc-quiz-builder" data-mc-practice-form><label>Chủ đề<select name="practiceTopic">'+D.practiceTopics.map(id=>'<option value="'+id+'"'+(id===selectedTopic?' selected':'')+'>'+esc(D.topic(id).title)+'</option>').join('')+'</select></label><label>Mức độ<select name="difficulty"><option value="basic">Cơ bản</option><option value="standard">Vận dụng</option><option value="advanced">Thử thách tính toán</option></select></label><label>Số câu<select name="count"><option>5</option><option>10</option><option>15</option><option>20</option></select></label><button class="mc-primary" type="submit">'+icon('target')+' Tạo bộ bài mới</button><small>Mức độ tăng độ lớn số liệu; bộ luyện này tập trung vào kỹ năng tính toán, chưa phải ngân hàng đề thi toàn diện.</small></form><section data-mc-quiz>'+quizView()+'</section>';}
    function quizView(){if(!quiz)return '<div class="mc-empty"><span>✦</span><h2>Sẵn sàng cho 5 câu đầu tiên?</h2><p>Chọn chủ đề và tạo một bộ bài của riêng em.</p></div>';const q=quiz[quizIndex],done=Object.keys(quizAnswers).length,total=quiz.length,correct=quiz.reduce((n,item)=>n+(quizAnswers[item.id]===item.correct?1:0),0);return (quizChecked?'<div class="mc-quiz-summary" role="status"><strong>'+correct+' / '+total+'</strong><div><h2>'+ (correct===total?'Em đã làm đúng cả bộ!':'Đã có kết quả. Cùng xem lại nhé.')+'</h2><p>'+ (total-correct)+' câu cần xem lại. Chọn từng câu để đọc giải thích.</p></div>'+button('retry-quiz','Tạo bộ tương tự')+'</div>':'')+'<article class="mc-panel mc-quiz-card"><div class="mc-quiz-meta"><span>Câu '+(quizIndex+1)+' / '+total+'</span><span>'+done+' câu đã chọn</span></div><progress max="'+total+'" value="'+done+'" aria-label="Số câu đã chọn"></progress><h2>'+esc(q.text)+'</h2><fieldset><legend class="mc-visually-hidden">Chọn một đáp án</legend>'+q.options.map((answer,i)=>'<label class="mc-option" data-correct="'+(quizChecked&&i===q.correct)+'" data-wrong="'+(quizChecked&&quizAnswers[q.id]===i&&i!==q.correct)+'"><input type="radio" name="quizAnswer" value="'+i+'"'+(quizAnswers[q.id]===i?' checked':'')+(quizChecked?' disabled':'')+'><span>'+String.fromCharCode(65+i)+'</span><b>'+esc(answer)+(q.unit?' <small>'+esc(q.unit)+'</small>':'')+'</b>'+(quizChecked&&i===q.correct?'<em>Đáp án đúng</em>':'')+'</label>').join('')+'</fieldset>'+(quizChecked?'<div class="mc-hint"><small>VÌ SAO?</small><p>'+esc(q.explanation)+'</p></div>':'')+'<div class="mc-actions">'+button('quiz-prev','← Câu trước',quizIndex===0?'disabled':'')+button('quiz-next','Câu tiếp →',quizIndex===total-1?'disabled':'')+(!quizChecked?button('submit-quiz','Nộp bài','class="mc-primary"'+(done<total?' disabled':'')):'')+'</div><nav class="mc-question-nav" aria-label="Chuyển câu">'+quiz.map((item,i)=>button('quiz-jump',String(i+1),'data-index="'+i+'" aria-label="Câu '+(i+1)+'" aria-pressed="'+(i===quizIndex)+'" data-answered="'+(quizAnswers[item.id]!==undefined)+'"')).join('')+'</nav></article>';}
    function labView(){return heading('NHÌN TOÁN HỌC TỪ MỘT GÓC KHÁC','Xoay hình. Cắt lớp. Khám phá đồ thị.','Thay đổi kích thước, quan sát thiết diện và nối công thức với hình ảnh tương tác.')+'<div class="mc-lab-grid"><section class="mc-panel mc-lab-panel"><div class="mc-panel-title"><div><small>KHÔNG GIAN 3 CHIỀU</small><h2>Phòng hình học</h2></div>'+icon('cube')+'</div><label>Khối hình<select name="shape"><option value="pyramid">Hình chóp đáy chữ nhật</option><option value="box">Hình hộp chữ nhật</option><option value="cylinder">Hình trụ</option><option value="cone">Hình nón</option><option value="sphere">Hình cầu</option></select></label><canvas data-mc-solid tabindex="0" role="img" aria-label="Mô hình hình học 3D. Kéo để xoay hoặc dùng phím mũi tên; Home để đặt lại góc nhìn."></canvas><div class="mc-dimension-fields">'+[['w','Dài',4],['d','Rộng',3],['h','Cao',5],['r','Bán kính',2]].map(([id,label,value])=>'<label data-mc-dimension="'+id+'">'+label+'<input type="number" name="'+id+'" min="0.5" max="10" step="0.5" value="'+value+'"></label>').join('')+'</div><label class="mc-cut-label">Độ cao mặt cắt <output data-mc-cut-label>50%</output><input type="range" name="cut" min="0" max="100" value="50"></label><div class="mc-inline"><label class="mc-toggle"><input type="checkbox" name="section" checked> Hiện thiết diện</label>'+button('solid-reset','Đặt lại góc nhìn')+'</div><div class="mc-solid-result" data-mc-solid-result aria-live="polite"></div><p class="mc-muted">Mặt cắt vàng song song với đáy. Dài, rộng, cao và bán kính dùng cùng đơn vị. Mô hình hỗ trợ quan sát, không thay thế chứng minh.</p></section><section class="mc-panel mc-lab-panel"><div class="mc-panel-title"><div><small>HÀM SỐ TƯƠNG TÁC</small><h2>Đồ thị & tiếp tuyến</h2></div><span class="mc-math-glyph">ƒ</span></div><form data-mc-graph-form class="mc-inline"><label>y = f(x)<input name="expression" value="x^2-4" maxlength="500" spellcheck="false" aria-describedby="mc-expression-help"></label><button class="mc-primary" type="submit">Vẽ</button></form><div class="mc-presets" role="group" aria-label="Đồ thị mẫu">'+['x^2-4','sin(x)','1/x','sqrt(x)'].map(value=>button('graph-preset',esc(value),'data-expression="'+esc(value)+'"')).join('')+'</div><canvas data-mc-graph tabindex="0" role="img" aria-label="Đồ thị hàm số. Di chuyển chuột hoặc dùng phím trái phải để xem tọa độ điểm."></canvas><div class="mc-graph-values" data-mc-graph-values aria-live="off"></div><label>Phạm vi trục x: −R đến R<input type="range" name="graphRange" min="2" max="16" step="1" value="6"></label><label class="mc-toggle"><input type="checkbox" name="tangent"> Hiện tiếp tuyến xấp xỉ tại điểm đang xem</label><p id="mc-expression-help" class="mc-muted">Dùng x, + − * / ^, ngoặc, pi, sin, cos, tan, sqrt, abs, ln, log, exp. Lượng giác dùng radian. Tiếp tuyến tính gần đúng bằng sai phân; điểm gián đoạn không có tiếp tuyến.</p><div data-mc-graph-error role="alert"></div></section></div>';}
    function casioView(){return heading('TÍNH NHANH, HIỂU ĐÚNG','Casio là công cụ. Tư duy là của em.','Hướng dẫn theo đúng dòng máy, kèm bài mẫu và cách kiểm tra kết quả. Chọn máy trước khi làm theo.')+'<div class="mc-casio-layout"><section class="mc-panel mc-calculator"><div class="mc-panel-title"><h2>Máy tính khoa học</h2>'+icon('calc')+'</div><p class="mc-muted">Công cụ HH để thử phép tính; không giả lập phần cứng hoặc toàn bộ chức năng Casio.</p><form data-mc-calculator><label>Biểu thức<input name="calcExpression" value="sin(30)" maxlength="500" spellcheck="false"></label><label>Đơn vị góc<select name="angleUnit"><option value="deg">DEG · Độ</option><option value="rad">RAD · Radian</option></select></label><div class="mc-calc-display"><small>KẾT QUẢ</small><output data-mc-calc-result aria-live="polite">—</output></div><div class="mc-keypad">'+['7','8','9','/','4','5','6','*','1','2','3','-','0','.','(',')','sin(','cos(','sqrt(','^'].map(k=>button('calc-key',esc(k),'data-key="'+esc(k)+'"')).join('')+button('calc-clear','AC')+button('calc-back','⌫','aria-label="Xóa ký tự trước con trỏ"')+button('calc-key','+','data-key="+"')+'<button type="submit" class="mc-primary">=</button></div></form><p class="mc-muted">Ưu tiên phép tính chuẩn. Hàm sin/cos/tan theo đơn vị góc; ln là logarit tự nhiên, log là cơ số 10.</p></section><div><label class="mc-model-picker">Dòng máy của em<select name="casioModel">'+['fx-580VN X','fx-880BTG'].map(model=>'<option'+(prefs.casioModel===model?' selected':'')+'>'+model+'</option>').join('')+'</select></label><div data-mc-casio-guides>'+casioGuides()+'</div></div></div>';}
    function casioGuides(){return D.casio.map((t,i)=>'<details class="mc-panel mc-casio-guide"'+(i===0?' open':'')+'><summary><span>0'+(i+1)+'</span><strong>'+esc(t.title)+'</strong></summary>'+formula(t.example)+'<ol>'+(prefs.casioModel==='fx-880BTG'?t.route880:t.route580).map(step=>'<li>'+esc(step)+'</li>').join('')+'<div class="mc-answer"><small>KẾT QUẢ ĐỐI CHIẾU</small><b>'+esc(t.expected)+'</b></div><p>'+esc(t.note)+'</p><a href="'+esc(D.manuals[prefs.casioModel].pdf)+'" target="_blank" rel="noopener noreferrer">Hướng dẫn chính thức Casio · '+esc(prefs.casioModel)+' ↗</a></details>').join('');}
    function notebookView(){const total=prefs.attempts.length,correct=prefs.attempts.filter(a=>a.correct).length;return heading('SỔ TAY CỦA EM','Giữ lại điều đã hiểu.','Bài đã lưu, ghi chú và kết quả từ những lần luyện tập trên thiết bị này. Dữ liệu tách theo tài khoản; ảnh bài làm không được lưu.')+(protectedState?'<aside class="mc-notice"><h2>Cần khôi phục sổ tay cũ</h2><p>Ứng dụng chưa đọc được phiên bản dữ liệu hiện có nên sẽ giữ nguyên bản gốc.</p><div class="mc-actions">'+button('backup','Tải bản gốc để khôi phục')+button('reset-state',resetArmed?'Xác nhận tạo sổ tay mới':'Tạo sổ tay mới')+'</div></aside>':'')+'<div class="mc-stats"><article><strong>'+total+'</strong><span>Câu đã nộp</span></article><article><strong>'+(total?Math.round(correct/total*100)+'%':'—')+'</strong><span>Tỉ lệ đúng trên '+total+' câu gần nhất</span></article><article><strong>'+prefs.saved.length+'</strong><span>Bài đã lưu</span></article></div><div class="mc-notebook-grid"><section class="mc-panel"><h2>Ghi chú của em</h2><label class="mc-visually-hidden" for="mc-notes">Nội dung ghi chú toán học</label><textarea id="mc-notes" name="notes" maxlength="30000" rows="10" placeholder="Công thức cần nhớ, lỗi mình hay gặp…"'+(protectedState?' disabled':'')+'>'+esc(prefs.notes)+'</textarea><div class="mc-inline"><small data-mc-note-status>Tự lưu trên thiết bị sau khi nhập.</small>'+button('export','Xuất sổ tay')+'</div></section><section class="mc-panel"><h2>Các bài đã lưu</h2>'+(prefs.saved.length?prefs.saved.map((item,i)=>'<article class="mc-saved"><small>'+esc(new Date(item.at).toLocaleDateString('vi-VN'))+' · '+(item.provider==='openai'?'AI trực tuyến':'Công cụ cục bộ')+'</small><h3>'+esc(item.problem)+'</h3><details><summary>Xem kết quả đã lưu</summary><p>'+esc(item.answer)+'</p></details>'+button('remove-saved','Bỏ lưu','data-index="'+i+'"')+'</article>').join(''):'<p class="mc-muted">Khi xem xong lời giải ở Trợ giảng, nhấn “Lưu vào sổ tay” để ôn lại sau.</p>')+'</section></div><section class="mc-panel"><h2>Những chủ đề cần luyện thêm</h2>'+reviewTopics()+'</section>';}
    function reviewTopics(){const rows=D.practiceTopics.map(id=>({id,attempts:prefs.attempts.filter(x=>x.topic===id)})).filter(row=>row.attempts.length);return rows.length?'<div class="mc-review-list">'+rows.map(row=>{const correct=row.attempts.filter(a=>a.correct).length;return link('practice','<strong>'+esc(D.topic(row.id).title)+'</strong><span>'+correct+'/'+row.attempts.length+' câu đúng · '+(row.attempts.length-correct)+' câu cần ôn</span>','data-mc-practice-topic="'+row.id+'"');}).join('')+'</div>':'<p class="mc-muted">Hoàn thành một bộ luyện tập để thấy kết quả theo chủ đề.</p>';}
    function render(){if(!alive)return;destroyGraphics();host.innerHTML='<section class="mc" data-mathcore><header class="mc-topbar"><a class="mc-brand" href="#/mathcore"><span>∑</span><div><strong>MATHCORE <b>AI</b></strong><small>Học bằng tư duy, tiến bộ từng ngày.</small></div></a><span class="mc-service" data-mc-service>'+esc(serviceMarkup())+'</span></header><nav class="mc-nav" aria-label="MATHCORE AI">'+tabs.map(([id,label,i])=>link(id,icon(i)+'<span>'+label+'</span>',view===id?'aria-current="page"':'')).join('')+'</nav><div class="mc-notice" data-mc-storage hidden></div><div class="mc-notice" data-mc-notice role="status"'+(!notice?' hidden':'')+'>'+esc(notice)+'</div><div class="mc-content">'+({tutor:tutorView,theory:theoryView,practice:practiceView,lab:labView,casio:casioView,notebook:notebookView}[view]||(()=>heading('KHÔNG TÌM THẤY','Mục này chưa có trong MATHCORE.', 'Hãy dùng thanh điều hướng phía trên để tiếp tục học.')))()+'</div><footer class="mc-footer"><span>MATHCORE AI · HH Learning</span><span>Đọc đề kỹ. Nêu điều kiện. Kiểm tra lại.</span></footer></section>';showStorage();updateService();if(view==='lab')mountGraphics();}
    function focusToken(container){const el=document.activeElement;if(!container?.contains(el))return null;return {action:el.dataset.mcAction,name:el.name,value:el.value,start:el.selectionStart,end:el.selectionEnd};}
    function restoreFocus(container,token){if(!token)return;const el=[...container.querySelectorAll('button,input,textarea')].find(el=>!el.disabled&&(token.action?el.dataset.mcAction===token.action:el.name===token.name&&(el.type!=='radio'||el.value===token.value)))||container.querySelector('textarea');if(el){el.focus({preventScroll:true});if(typeof token.start==='number'&&el.setSelectionRange)try{el.setSelectionRange(token.start,token.end);}catch{}}}
    function renderGuidance(){const el=host.querySelector('[data-mc-guidance]'),focus=focusToken(el);if(el){el.innerHTML=guidance();restoreFocus(el,focus);}host.querySelectorAll('[data-mc-tutor-form] button[type=submit], [data-mc-tutor-form] [name=online]').forEach(el=>{el.disabled=busy||(el.hasAttribute('data-mc-requires-ai')&&(!canAI()||!photo))||(el.name==='online'&&!canAI());});}
    function localLesson(sample=false){const t=topic();let result;if(sample||C.normalize(problem)===C.normalize(t.problem)){result={...t,title:t.title,provider:'local',conditions:[t.conditions],problem:t.problem};problem=t.problem;const input=host.querySelector('[name=problem]');if(input)input.value=problem;}
      else{try{result=C.solveEquation(problem);selectedTopic=result.topic;const select=host.querySelector('[name=topic]');if(select)select.value=selectedTopic;if(attempt.trim())localChecks=C.checkLines(problem,attempt);}
        catch(error){result={...t,title:'Cùng ôn lại: '+t.title,provider:'local',conditions:[t.conditions]};result.reference='Chưa tự giải được chính xác đề vừa nhập bằng công cụ cục bộ. Dưới đây là gợi ý theo chủ đề và ví dụ mẫu; không phải đáp án cho đề của em. '+error.message;result.problem=t.problem;result.conditions=[t.conditions];result.steps=t.steps;result.answer='Ví dụ mẫu: '+t.answer;result.alternative=t.reflect;}}
      return result;
    }
    function cancelPending(){requestVersion++;request?.abort();request=null;ocrSession?.destroy();ocrSession=null;root.clearTimeout(ocrTimer);busy=false;}
    async function requestTutor(reveal=false){if(busy)return;feedback('');localChecks=[];if(!problem.trim()){feedback('Em hãy nhập đề bài hoặc nhấn “Thử bài mẫu”.');host.querySelector('[name=problem]')?.focus();return;}if(!online){lesson=localLesson();hintIndex=0;revealed=reveal;renderGuidance();return;}if(!canAI()){feedback(serviceMarkup()+'.');return;}
      busy=true;const ticket=++requestVersion,question=problem,work=attempt,chosen=selectedTopic;request=new AbortController();renderGuidance();try{const data=await api('tutor',{question,attempt:work,topic:chosen,reveal},AbortSignal.any([request.signal,lifecycle.signal,AbortSignal.timeout(29000)]));if(!alive||ticket!==requestVersion)return;lesson={...data.result,problem:question};revealed=reveal;hintIndex=0;}catch(error){if(alive&&ticket===requestVersion&&error.name!=='AbortError')feedback(error.message);}finally{if(alive&&ticket===requestVersion){busy=false;request=null;renderGuidance();updateService();}}}
    async function requestPhoto(){if(busy||!photo)return;if(!canAI()){feedback(serviceMarkup()+'.');return;}busy=true;const ticket=++requestVersion;request=new AbortController();feedback('');renderGuidance();try{const data=await api('photo',{question:problem||'Hãy đọc và kiểm tra các bước giải trong ảnh.',attempt:'',topic:selectedTopic,image:{mimeType:'image/jpeg',data:photo.data}},AbortSignal.any([request.signal,lifecycle.signal,AbortSignal.timeout(29000)]));if(!alive||ticket!==requestVersion)return;photoResult={...data.result,provider:'openai'};render();}catch(error){if(alive&&ticket===requestVersion&&error.name!=='AbortError')feedback(error.message);}finally{if(alive&&ticket===requestVersion){busy=false;request=null;renderGuidance();updateService();}}}
    async function requestOCR(){if(busy||!photo)return;const ticket=++requestVersion,source=photo;busy=true;feedback('');renderGuidance();ocrSession=root.HHMathCoreOCR.create();const session=ocrSession;let timedOut=false,timeout=0;
      try{const data=await Promise.race([session.recognize(Uint8Array.from(root.atob(source.data),c=>c.charCodeAt(0)),message=>{const p=host.querySelector('.mc-working p');if(alive&&ticket===requestVersion&&p)p.textContent='Nhận chữ trên thiết bị · '+Math.round((message.progress||0)*100)+'%';}),new Promise((resolve,reject)=>{timeout=ocrTimer=root.setTimeout(()=>{timedOut=true;session.destroy();reject(Error('Nhận chữ mất quá lâu. Hãy thử ảnh nhỏ hơn hoặc nhập các dòng bài làm.'));},60000);})]);if(!alive||ticket!==requestVersion)return;const lines=root.HHMathCoreOCR.lines(data,source.width,source.height),readBack=(lines.length?lines.map(l=>l.text).join('\n'):String(data.text||'')).slice(0,9000);photoResult={provider:'ocr-local',readBack,lines,edited:false,summary:readBack?'Đã quét chữ trên thiết bị. Hãy sửa những ký hiệu đọc sai, kiểm tra đề gốc bên trái rồi nhấn đối chiếu.':'Chưa đọc được chữ rõ ràng. Hãy chụp gần hơn, đủ sáng hoặc nhập lại bài làm.',observations:[],uncertainties:['OCR phù hợp với chữ in rõ; có thể đọc sai chữ viết tay, phân số xếp dọc và dấu mũ.'],nextHint:'Hãy kiểm tra dấu cộng, dấu trừ, số mũ và từng dòng trong bản chép trước khi đối chiếu.'};render();}
      catch(error){if(alive&&ticket===requestVersion&&(error.name!=='AbortError'||timedOut))feedback(error.message||'Chưa nhận được chữ từ ảnh.');}finally{root.clearTimeout(timeout);if(ocrTimer===timeout)ocrTimer=0;session.destroy();if(alive&&ticket===requestVersion){ocrSession=null;busy=false;renderGuidance();updateService();}}
    }
    function compareOCR(){if(!photoResult||photoResult.provider!=='ocr-local')return;try{if(!problem.trim())throw Error('Hãy nhập phương trình gốc ở ô Đề bài để làm mốc đối chiếu.');const rows=C.checkLines(problem,photoResult.readBack);if(!rows.length)throw Error('Bản chép chưa có dòng để đối chiếu.');photoResult.observations=rows.map(row=>({quote:row.text,status:row.status==='unread'?'uncertain':row.status,note:row.note,box:!photoResult.edited?(photoResult.lines.find(l=>l.text===row.text&&l.confidence>=65)?.box||null):null}));photoResult.summary='Đã đối chiếu '+rows.length+' dòng theo phương trình gốc em cung cấp.';photoResult.nextHint=rows.find(r=>r.status==='review')?.note||'Hãy thử lại nghiệm trong phương trình gốc và nêu đầy đủ điều kiện.';feedback('');render();}catch(error){feedback(error.message);host.querySelector('[name=problem]')?.focus();}}
    async function choosePhoto(file){cancelPending();const sequence=++imageSequence;if(!file)return;if(file.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){feedback('Chọn ảnh JPEG, PNG hoặc WebP tối đa 10 MB.');return;}if(!root.createImageBitmap){feedback('Trình duyệt này chưa hỗ trợ đọc ảnh. Hãy dùng Chrome, Edge hoặc Safari phiên bản hỗ trợ createImageBitmap.');return;}feedback('Đang chuẩn bị ảnh…');let bitmap;
      try{bitmap=await root.createImageBitmap(file);if(!alive||sequence!==imageSequence)return;if(bitmap.width<16||bitmap.height<16||bitmap.width*bitmap.height>40000000)throw Error('Ảnh quá nhỏ hoặc vượt 40 triệu điểm ảnh. Hãy chụp lại phần bài cần kiểm tra.');const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);const ctx=canvas.getContext('2d');if(!ctx)throw Error('Trình duyệt chưa hỗ trợ xử lý ảnh.');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.86));if(blob?.size>1500000)blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.65));if(!blob||blob.size>1600000)throw Error('Ảnh vẫn quá lớn. Hãy chọn vùng bài nhỏ hơn.');const reader=new FileReader();const data=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Chưa đọc được ảnh.'));reader.readAsDataURL(blob);});if(!alive||sequence!==imageSequence)return;if(photo)URL.revokeObjectURL(photo.url);photo={data,bytes:blob.size,width:canvas.width,height:canvas.height,url:URL.createObjectURL(blob)};photoResult=null;feedback('');render();}catch(error){if(alive&&sequence===imageSequence)feedback(error.message||'Chưa mở được ảnh.');}finally{bitmap?.close();}}
    function mountGraphics(){try{solid=root.HHMathCoreGraphics.mountSolid(host.querySelector('[data-mc-solid]'));graph=root.HHMathCoreGraphics.mountGraph(host.querySelector('[data-mc-graph]'),{onTrace:data=>{const el=host.querySelector('[data-mc-graph-values]');if(el)el.textContent='x = '+C.fmt(data.x)+' · f(x) = '+C.fmt(data.y)+(host.querySelector('[name=tangent]')?.checked?' · f′(x) ≈ '+C.fmt(data.derivative):'');}});updateSolid();}catch(error){feedback('Chưa khởi tạo được hình tương tác: '+error.message);}}
    function updateSolid(){if(!solid)return;const read=name=>host.querySelector('[name='+name+']'),shape=read('shape').value,dim={w:Number(read('w').value),d:Number(read('d').value),h:Number(read('h').value),r:Number(read('r').value)},state={...dim,shape,cut:Number(read('cut').value),section:read('section').checked};solid.update(state);host.querySelector('[data-mc-cut-label]').textContent=state.cut+'%';host.querySelectorAll('[data-mc-dimension]').forEach(el=>{const name=el.dataset.mcDimension;el.hidden=shape==='sphere'?name!=='r':shape==='cone'||shape==='cylinder'?!['h','r'].includes(name):name==='r';});const m=C.solidMeasure(shape,dim),out=host.querySelector('[data-mc-solid-result]');out.innerHTML='<span>'+esc(m.formula)+'</span><strong>V = '+C.fmt(m.volume)+' <small>đơn vị³</small></strong>'+(m.area?'<span>Diện tích toàn phần = '+C.fmt(m.area)+' đơn vị²</span>':'');}
    function updateGraph(expression){try{graph?.update({...(expression!==undefined?{expression}:{}),range:Number(host.querySelector('[name=graphRange]').value),tangent:host.querySelector('[name=tangent]').checked});host.querySelector('[data-mc-graph-error]').textContent='';}catch(error){host.querySelector('[data-mc-graph-error]').textContent=error.message;}}
    function renderQuiz(){const target=host.querySelector('[data-mc-quiz]'),focus=focusToken(target);target.innerHTML=quizView();restoreFocus(target,focus);}
    function newQuiz(){const form=host.querySelector('[data-mc-practice-form]'),data=new FormData(form);selectedTopic=String(data.get('practiceTopic'));const seed=new Uint32Array(1);root.crypto.getRandomValues(seed);quiz=C.practice(selectedTopic,String(data.get('difficulty')),Number(data.get('count')),seed[0]);quizAnswers={};quizChecked=false;quizIndex=0;prefs.topic=selectedTopic;persist();renderQuiz();}
    function exportFile(value,name){const blob=new Blob([value],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();root.setTimeout(()=>URL.revokeObjectURL(url),1000);}
    function saveLesson(){if(!lesson||!revealed)return;if(protectedState){feedback('Hãy khôi phục sổ tay trước khi lưu bài mới.');return;}const item={problem:lesson.problem||problem,answer:lesson.answer||'',at:new Date().toISOString(),provider:lesson.provider};prefs.saved=[item,...prefs.saved.filter(x=>x.problem!==item.problem)].slice(0,100);if(persist())feedback('Đã lưu bài vào Sổ tay trên thiết bị này.');}
    function onClick(event){const anchor=event.target.closest('[data-mc-practice-topic]');if(anchor){prefs.topic=anchor.dataset.mcPracticeTopic;persist();return;}const el=event.target.closest('[data-mc-action]');if(!el||el.disabled)return;const action=el.dataset.mcAction;
      if(action==='focus-problem'){const input=host.querySelector('[name=problem]');input?.focus({preventScroll:true});input?.scrollIntoView({block:'center',behavior:root.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}
      else if(action==='mode'){cancelPending();mode=el.dataset.mode;render();}
      else if(action==='ocr')requestOCR();
      else if(action==='compare-ocr')compareOCR();
      else if(action==='sample'){cancelPending();localChecks=[];lesson=localLesson(true);hintIndex=0;revealed=false;mode='text';prefs.draft={problem,attempt};scheduleSave();render();}
      else if(action==='study-sample'){prefs.topic=selectedTopic;prefs.draft={problem:topic().problem,attempt:''};persist();location.hash='/mathcore?topic='+encodeURIComponent(selectedTopic);}
      else if(action==='next-hint'||action==='prev-hint'){hintIndex=Math.max(0,Math.min(lesson.hints.length-1,hintIndex+(action==='next-hint'?1:-1)));renderGuidance();}
      else if(action==='check-thinking'){if(!lesson?.thinking?.trim()){feedback('Em hãy viết bước định làm, ví dụ 2x = 8.');host.querySelector('[name=thinking]')?.focus();return;}attempt=lesson.thinking;const input=host.querySelector('[name=attempt]');if(input){input.value=attempt;input.closest('details').open=true;}prefs.draft={problem,attempt};scheduleSave();if(lesson.provider==='openai'){online=true;requestTutor();}else{try{localChecks=C.checkLines(lesson.problem,attempt);renderGuidance();feedback('Đã đối chiếu bước em viết với đề gốc.');}catch{feedback('Bước này cần trợ giảng AI hoặc lời giải ví dụ để đối chiếu; công cụ cục bộ chỉ kiểm tra phương trình bậc 1–2.');}}}
      else if(action==='reveal'){if(lesson?.provider==='openai'&&!lesson.answer){requestTutor(true);}else{revealed=!revealed;renderGuidance();}}
      else if(action==='save')saveLesson();
      else if(action==='cancel'){cancelPending();renderGuidance();updateService();feedback('Đã hủy yêu cầu.');}
      else if(action==='remove-photo'){cancelPending();imageSequence++;if(photo)URL.revokeObjectURL(photo.url);photo=null;photoResult=null;render();}
      else if(action==='topic'){selectedTopic=el.dataset.topic;prefs.topic=selectedTopic;persist();host.querySelector('[data-mc-theory-detail]').innerHTML=theoryDetail();host.querySelector('[data-mc-topic-list]').innerHTML=topicList();host.querySelector('[data-mc-theory-detail] h2')?.setAttribute('tabindex','-1');host.querySelector('[data-mc-theory-detail] h2')?.focus({preventScroll:true});}
      else if(action==='solid-reset')solid?.reset();
      else if(action==='graph-preset'){host.querySelector('[name=expression]').value=el.dataset.expression;updateGraph(el.dataset.expression);}
      else if(action==='quiz-prev'||action==='quiz-next'){quizIndex=Math.max(0,Math.min(quiz.length-1,quizIndex+(action==='quiz-next'?1:-1)));renderQuiz();}
      else if(action==='quiz-jump'){quizIndex=Number(el.dataset.index);renderQuiz();}
      else if(action==='submit-quiz'){if(quizChecked||!quiz||Object.keys(quizAnswers).length!==quiz.length)return;quizChecked=true;const now=new Date().toISOString();prefs.attempts=[...prefs.attempts,...quiz.map(q=>({id:q.id,topic:q.topic,correct:quizAnswers[q.id]===q.correct,at:now}))].slice(-500);persist();renderQuiz();}
      else if(action==='retry-quiz')newQuiz();
      else if(action==='calc-key'){const input=host.querySelector('[name=calcExpression]'),start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(el.dataset.key,start,end,'end');input.focus({preventScroll:true});}
      else if(action==='calc-clear'){host.querySelector('[name=calcExpression]').value='';host.querySelector('[data-mc-calc-result]').textContent='—';}
      else if(action==='calc-back'){const input=host.querySelector('[name=calcExpression]'),start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText('',start===end?Math.max(0,start-1):start,end,'end');input.focus({preventScroll:true});}
      else if(action==='remove-saved'){prefs.saved.splice(Number(el.dataset.index),1);persist();render();}
      else if(action==='export')exportFile(JSON.stringify({...prefs,exportedAt:new Date().toISOString()},null,2),'mathcore-notebook.json');
      else if(action==='backup')exportFile(rawBackup||'null','mathcore-original-backup.json');
      else if(action==='reset-state'){if(!resetArmed){resetArmed=true;render();return;}protectedState=false;prefs=C.defaults();if(persist()){rawBackup=null;resetArmed=false;render();}else protectedState=true;}
    }
    function onInput(event){const el=event.target;if(el.name==='problem'||el.name==='attempt'){if(el.name==='problem')problem=el.value;else attempt=el.value;prefs.draft={problem,attempt};scheduleSave();}
      else if(el.name==='ocrReadBack'&&photoResult){photoResult.readBack=el.value;photoResult.edited=true;photoResult.observations=[];host.querySelector('.mc-photo-boxes')?.replaceChildren();const findings=host.querySelector('[data-mc-photo-findings]');if(findings)findings.textContent='Nội dung đã thay đổi. Hãy đối chiếu lại sau khi sửa.';}
      else if(el.name==='thinking'&&lesson)lesson.thinking=el.value;
      else if(el.name==='notes'){prefs.notes=el.value;scheduleSave();const status=host.querySelector('[data-mc-note-status]');if(status)status.textContent='Ghi chú sẽ được tự lưu trên thiết bị.';}
      else if(el.name==='theoryQuery'){theoryQuery=el.value;host.querySelector('[data-mc-topic-list]').innerHTML=topicList();}
      else if(['w','d','h','r','cut'].includes(el.name))updateSolid();
      else if(el.name==='graphRange')updateGraph();
    }
    function onChange(event){const el=event.target;if(el.name==='topic'){selectedTopic=el.value;prefs.topic=selectedTopic;persist();}else if(el.name==='online')online=el.checked;else if(el.name==='photo'||el.name==='camera')choosePhoto(el.files?.[0]);else if(el.name==='shape'||el.name==='section')updateSolid();else if(el.name==='tangent')updateGraph();else if(el.name==='casioModel'){prefs.casioModel=el.value;persist();host.querySelector('[data-mc-casio-guides]').innerHTML=casioGuides();}else if(el.name==='quizAnswer'&&!quizChecked){quizAnswers[quiz[quizIndex].id]=Number(el.value);renderQuiz();}}
    function onSubmit(event){if(event.target.matches('[data-mc-tutor-form]')){event.preventDefault();if(mode==='photo')requestPhoto();else requestTutor();}else if(event.target.matches('[data-mc-practice-form]')){event.preventDefault();newQuiz();}else if(event.target.matches('[data-mc-graph-form]')){event.preventDefault();updateGraph(host.querySelector('[name=expression]').value);}else if(event.target.matches('[data-mc-calculator]')){event.preventDefault();const out=host.querySelector('[data-mc-calc-result]');try{out.textContent=C.fmt(C.calculator(host.querySelector('[name=calcExpression]').value,host.querySelector('[name=angleUnit]').value));}catch(error){out.textContent=error.message;}}}
    function ownerChanged(event){const user=event.detail?.user;if(C.preferenceKey(user)!==key||Boolean(user?.guest)!==Boolean(owner?.guest))mount(host,{...options,currentUser:user});}
    function storageChanged(event){if(event.key===key&&alive){root.clearTimeout(saveTimer);rawBackup=event.newValue;try{prefs=C.preferences(event.newValue===null?null:JSON.parse(event.newValue));protectedState=false;feedback('Sổ tay đã thay đổi ở một cửa sổ khác.');}catch{protectedState=true;}if(view==='notebook')render();else showStorage();}}
    host.addEventListener('click',onClick);host.addEventListener('input',onInput);host.addEventListener('change',onChange);host.addEventListener('submit',onSubmit);root.addEventListener('hh:auth-change',ownerChanged);root.addEventListener('storage',storageChanged);
    active={destroy(){root.clearTimeout(saveTimer);if(!protectedState)persist();alive=false;lifecycle.abort();cancelPending();imageSequence++;if(photo)URL.revokeObjectURL(photo.url);destroyGraphics();host.removeEventListener('click',onClick);host.removeEventListener('input',onInput);host.removeEventListener('change',onChange);host.removeEventListener('submit',onSubmit);root.removeEventListener('hh:auth-change',ownerChanged);root.removeEventListener('storage',storageChanged);}};
    render();api('status',null,lifecycle.signal).then(data=>{if(alive){service=data;updateService();}}).catch(error=>{if(alive&&error.name!=='AbortError'){serviceError=error.message;updateService();}});return true;
  }
  function unmount(){active?.destroy();active=null;}
  root.HHMathCoreAI=Object.freeze({mount,unmount});
})(window);
